import {session,storageKey,api,logout} from './session.mjs';
import {directoryFields,validDirectory,migrateDirectories,applyContact} from './contacts.mjs';
import {travelTemplate} from './travel-template.mjs';
import {eventDates,validDate,costTotal,travelCalc,round} from './calc.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('uk-UA',{minimumFractionDigits:2,maximumFractionDigits:2}),num=n=>Number(n).toLocaleString('uk-UA',{maximumFractionDigits:2});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('uk-UA'):'__________';
const longDate=s=>{if(!s)return '________________';const d=new Date(s+'T12:00:00');return `«${String(d.getDate()).padStart(2,'0')}» ${['січня','лютого','березня','квітня','травня','червня','липня','серпня','вересня','жовтня','листопада','грудня'][d.getMonth()]} ${d.getFullYear()} року`};
const defaults=()=>({version:1,event:{venue:'',date:today(),receiptDate:'',number:'',city:'Київ',person:'',products:['Дона'],items:['Чай','Кава','Цукерки','Печиво'].map(name=>({name,qty:1,price:0}))},profile:{company:'«МЕДА Фармасьютікалз Світселенд ГмБх»',head:'В. С. Піонт',budgetHead:'Піонт В.С.',position:'Голова представництва'},products:['Дона','Целебрекс','Лірика','Алдара','Елідел'],travel:{liters:0,rate:10,startFuel:20,endTarget:20,adjustmentKm:0,refill:0,odometer:12675.7,basis:'seat · вересень 2026 · D21/F21/G21',driver:'',car:'SEAT',plate:'',from:today(),to:today(),rows:[{date:today(),route:'',km:0}]},archive:[]});
let state=defaults(),storageOK=true,view='event',eventTab='details',docType='order',deferredInstall;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||(session.user.role==='admin'?localStorage.getItem('zvit-v1'):null));if(saved&&saved.version===1&&saved.event&&saved.travel&&Array.isArray(saved.archive))state={...state,...saved,profile:{...state.profile,...saved.profile}}}catch{storageOK=false}
migrateDirectories(state);
state.travel.endTarget ??= state.travel.startFuel;state.travel.adjustmentKm ??= 0;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true;$('#save-state').textContent='● Збережено на пристрої'}catch{storageOK=false;$('#save-state').textContent='Не збережено · зробіть резервну копію'}$('#archive-count').textContent=state.archive.length}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function field(label,key,value,type='text',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" data-key="${key}" value="${esc(value)}" ${extra}></label>`}
const btn=(text,action,cls='button')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
const head=(eyebrow,title,desc,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;
function eventView(){return head('ДОКУМЕНТИ ПОДІЇ','Одна подія. Усі документи.','Заповніть дані один раз — наказ і кошторис сформуються разом.',btn('＋ Нова подія','new-event','button secondary')+btn('Зберегти звіт ↗','save-event'))+`<div class="summary-strip"><div><span class="summary-icon">▤</span><span><b>Наказ + кошторис</b><small>Спільні дані, два документи</small></span></div><div><span class="summary-icon">▧</span><span><b>Готові до друку</b><small>Формат A4 · збереження у PDF</small></span></div><div><span class="summary-icon">✓</span><span><b>За вашими зразками</b><small>Наказ і кошторис із PDF</small></span></div></div><div class="editor-layout"><section class="card editor-card"><div class="tabs"><button data-tab="details" class="${eventTab==='details'?'selected':''}">01 <span>Дані події</span></button><button data-tab="budget" class="${eventTab==='budget'?'selected':''}">02 <span>Кошторис</span></button></div><div class="card-body">${eventTab==='details'?eventFields():budgetFields()}</div><div class="card-bottom"><span>↳ Зміни одразу з’являться в документах</span>${btn(eventTab==='details'?'До кошторису →':'← Дані події','next-tab','text-button')}</div></section><aside class="preview-column"><div class="preview-heading"><h2>Ваші документи</h2><span class="pill">A4</span></div><div class="document-switch"><button data-doc="order" class="${docType==='order'?'selected':''}">Наказ</button><button data-doc="budget" class="${docType==='budget'?'selected':''}">Кошторис</button></div><button class="preview-shell" data-action="preview" aria-label="Розгорнути перегляд документа"><div id="mini-doc" class="mini-doc"></div><span class="preview-expand">⤢ Розгорнути</span></button><div class="preview-caption"><span class="status-dot"></span><span id="preview-status"></span></div><div class="print-actions">${btn('⎙ Друк / PDF','print')}${btn('Друкувати обидва','print-both','button secondary')}</div><p class="print-help">У вікні друку виберіть A4, масштаб 100% та вимкніть колонтитули.</p></aside></div>`}
function eventFields(){const e=state.event;return `<div class="section-heading"><h2>Про круглий стіл</h2><p>Ці дані використовуються в обох документах.</p></div>${contactPicker('clinics')}${field('Назва закладу <em>*</em>','event.venue',e.venue,'text','placeholder="Наприклад, МЦ Леодерм" maxlength="180"')}<div class="field-grid">${field('Дата круглого столу <em>*</em>','event.date',e.date,'date','required')}${field('Дата чеку <em>*</em>','event.receiptDate',e.receiptDate||'','date','required')}<label class="field"><span>Дата наказу <span class="auto-label">автоматично</span></span><input id="order-date" class="readonly" value="${date(eventDates(e).orderDate)}" readonly><small>За один день до дати чеку</small></label>${field('Номер наказу','event.number',e.number,'text','placeholder="Наприклад, 24/11" maxlength="40"')}${field('Місто','event.city',e.city,'text','maxlength="80"')}</div>${contactPicker('representatives')}${field('Відповідальна особа <em>*</em>','event.person',e.person,'text','placeholder="Кому: прізвище, ім’я, по батькові" maxlength="180"')}<p class="field-help">У давальному відмінку: «Кузьмінській Уляні Іванівні».</p><div class="contact-save">${btn('Зберегти клініку','remember-clinic','button secondary')}${btn('Зберегти представника','remember-representative','button secondary')}${btn('Довідники →','manage-contacts','text-button')}</div><div class="section-divider"></div><h3>Препарати <em>*</em></h3><p class="muted">Оберіть один або кілька препаратів.</p><div class="chips">${state.products.map(p=>`<button class="chip ${e.products.includes(p)?'checked':''}" data-product="${esc(p)}" aria-pressed="${e.products.includes(p)}">${e.products.includes(p)?'✓':'＋'} ${esc(p)}</button>`).join('')}</div><div class="inline-add"><input id="new-product" placeholder="Інший препарат" aria-label="Назва нового препарату" maxlength="80">${btn('Додати','add-product','button secondary')}</div><div class="note"><span>↔</span><p>Дата наказу й кошторису — за день до дати чеку. Дата круглого столу вказується окремо. Препарати вказуються в наказі, відповідно до зразка.</p></div>`}
function budgetFields(){return `<div class="section-heading"><h2>Витрати на подію</h2><p>Додайте потрібні позиції. Сума рахується автоматично.</p></div><div class="budget-labels"><span>Позиція</span><span>К-сть</span><span>Ціна, ₴</span><span></span></div><div class="budget-rows">${state.event.items.map((r,i)=>`<div class="budget-row"> <input aria-label="Позиція ${i+1}" data-item="${i}" data-prop="name" value="${esc(r.name)}" maxlength="120"><input aria-label="Кількість ${i+1}" data-item="${i}" data-prop="qty" type="number" min="0.01" step="0.01" value="${r.qty}"><input aria-label="Ціна ${i+1}" data-item="${i}" data-prop="price" type="number" min="0" step="0.01" value="${r.price}"><button class="icon-button remove" data-remove-item="${i}" aria-label="Видалити позицію ${i+1}">×</button><small>Сума: <b data-line-total="${i}">${money(r.qty*r.price)} ₴</b></small></div>`).join('')}</div>${btn('＋ Додати позицію','add-item','button secondary dashed')}<div class="budget-total"><span>Усього за подію</span><strong id="budget-total">${money(costTotal(state.event.items))} <small>₴</small></strong></div><p class="field-help">У друкованому кошторисі — опис затрат і підсумкова сума позиції, як у вашому зразку.</p>`}
function travelView(){return head('ПОДОРОЖНІЙ ЛИСТ','Літри → кілометри → звіт.','Вкажіть витрачені літри. Решта розрахується за логікою вашого Excel.',btn('Наступний період →','next-period','button secondary')+btn('Зберегти звіт ↗','save-travel'))+`<div class="notice"><b>Ваш бланк A5 · дві сторони</b><p>Розрахунки перенесено з Excel. Видано = витрачено + кінцевий залишок − початковий. Ручна поправка пробігу перераховує фактичну витрату.</p></div><div class="travel-layout"><section class="card"><div class="card-body"><h2>Пальне та автомобіль</h2>${contactPicker('representatives','travel')}<div class="button-row">${btn('SEAT · 10 л/100 км','preset-seat','button secondary')}${btn('VW · 9 л/100 км','preset-vw','button secondary')}</div><p class="source-note">Початкові дані: ${esc(state.travel.basis||'введені вручну')}. Перевірте, якщо були наступні поїздки.</p><div class="field-grid">${field('Витрачено за період, л *','travel.liters',state.travel.liters,'number','min="0.01" step="0.01"')}${field('Норма, л / 100 км *','travel.rate',state.travel.rate,'number','min="0.01" step="0.01"')}${field('Залишок на початок, л','travel.startFuel',state.travel.startFuel,'number','min="0" step="0.01"')}${field('Залишок на кінець, л','travel.endTarget',state.travel.endTarget,'number','min="0" step="0.01"')}${field('Поправка пробігу, ± км','travel.adjustmentKm',state.travel.adjustmentKm,'number','step="0.1"')}<label class="field"><span>Розраховано виданого пального, л</span><input id="auto-refill" readonly class="readonly" value="${num(travelCalc(state.travel).refill??0)}"><small>Витрачено + залишок на кінець − залишок на початок</small></label>${field('Початок періоду','travel.from',state.travel.from,'date')}${field('Кінець періоду','travel.to',state.travel.to,'date')}${field('Водій *','travel.driver',state.travel.driver,'text','maxlength="180"')}${field('Автомобіль *','travel.car',state.travel.car,'text','maxlength="120"')}${field('Державний номер *','travel.plate',state.travel.plate,'text','maxlength="30"')}${field('Одометр на початок, км','travel.odometer',state.travel.odometer,'number','min="0" step="0.01"')}</div><details class="travel-details"><summary>Реквізити бланка та час роботи</summary><div class="field-grid">${field('Номер подорожнього листа','travel.number',state.travel.number||'','text','maxlength="30"')}${field('Режим роботи водія','travel.workMode',state.travel.workMode||'','text','maxlength="80"')}${field('Марка пального','travel.fuelBrand',state.travel.fuelBrand||'','text','maxlength="30"')}${field('Код марки пального','travel.fuelCode',state.travel.fuelCode||'','text','maxlength="20"')}${field('Час виїзду','travel.departTime',state.travel.departTime||'','time')}${field('Час повернення','travel.returnTime',state.travel.returnTime||'','time')}${field('Час у наряді, год','travel.hours',state.travel.hours||'','number','min="0" step="0.1"')}${field('Колона','travel.column',state.travel.column||'','text','maxlength="30"')}${field('Бригада','travel.brigade',state.travel.brigade||'','text','maxlength="30"')}</div>${field('Особливі відмітки','travel.notes',state.travel.notes||'','text','maxlength="300"')}</details><div class="section-divider"></div><h2>Поїздки</h2><p class="muted">Остання поїздка отримує решту пробігу. Кнопки ± змінюють попередні поїздки на 1 км.</p><div id="trip-rows">${tripRows()}</div>${btn('＋ Додати поїздку','add-trip','button secondary dashed')}${btn('Розподілити порівну','split-trips','text-button')}</div></section><aside><div class="card balance-card"><span class="eyebrow">БАЛАНС ЗА ПЕРІОД</span><div id="travel-balance"></div><div class="section-divider"></div>${btn('Перегляд A5','travel-preview','button secondary wide')}${btn('⎙ Друк / PDF','print-travel','button wide')}<p class="print-help">Дві сторінки A5. Для друку з обох боків виберіть перевертання по довгому краю. Підписи заповнюються на папері.</p></div></aside></div>`}
function tripRows(){const result=travelCalc(state.travel);return state.travel.rows.map((r,i)=>{const last=i===state.travel.rows.length-1;return `<div class="trip-row"><div class="trip-row-top"><b>Поїздка ${i+1}${last?' · залишок':''}</b><button class="icon-button" data-remove-trip="${i}" aria-label="Видалити поїздку ${i+1}" ${state.travel.rows.length===1?'disabled':''}>×</button></div><div class="field-grid"><label class="field"><span>Дата</span><input type="date" data-trip="${i}" data-prop="date" value="${esc(r.date)}"></label><label class="field"><span>Пробіг, км${last?' · авто':''}</span><div class="stepper">${last?'':`<button data-step-trip="${i}" data-step="-1" aria-label="Зменшити пробіг поїздки ${i+1}">−</button>`}<input type="number" min="0" step="0.01" aria-label="Пробіг поїздки ${i+1}" data-trip="${i}" data-prop="km" value="${last?result.rows?.[i]?.km??0:r.km}" ${last?'readonly data-last-km':''}>${last?'':`<button data-step-trip="${i}" data-step="1" aria-label="Збільшити пробіг поїздки ${i+1}">+</button>`}</div></label></div><input aria-label="Маршрут поїздки ${i+1}" placeholder="Маршрут: звідки → куди" data-trip="${i}" data-prop="route" value="${esc(r.route)}" maxlength="200"></div>`}).join('')}
function archiveView(){return head('ЗБЕРЕЖЕНІ ЗВІТИ','Усе під рукою.','Збережені версії документів на цьому пристрої.',btn('↓ Резервна копія','backup','button secondary'))+`<section class="card"><div class="card-body"><label class="field"><span>Пошук звіту</span><input id="archive-search" placeholder="Назва закладу або водій"></label><div id="archive-list">${archiveList('')}</div></div></section>`}
function archiveList(q){const rows=state.archive.filter(r=>r.title.toLowerCase().includes(q.toLowerCase()));return rows.length?rows.slice().reverse().map(r=>`<div class="archive-row"><span class="summary-icon">${r.type==='event'?'▤':'↗'}</span><div><h3>${esc(r.title)}</h3><p>${r.type==='event'?'Наказ + кошторис':'Подорожній лист'} · ${date(r.date)}</p></div>${btn('Відкрити','open-'+r.id,'button secondary')}<button class="icon-button" data-delete-archive="${r.id}" aria-label="Видалити звіт ${esc(r.title)}">×</button></div>`).join(''):`<div class="empty-state"><span>▣</span><h2>${q?'Звітів не знайдено':'Тут будуть ваші звіти'}</h2><p>Заповніть документ і натисніть «Зберегти звіт».</p></div>`}
function settingsView(){return head('НАЛАШТУВАННЯ','Деталі, які не треба повторювати.','Реквізити, резервні копії та встановлення застосунку.')+`<div class="settings-layout"><section class="card"><div class="card-body">${accountSettings()}<h2>Підписант документів</h2><p class="muted">Початкові реквізити перенесено з ваших PDF-зразків.</p>${field('Організація','profile.company',state.profile.company,'text','maxlength="200"')}${field('Посада','profile.position',state.profile.position,'text','maxlength="120"')}${field('Підписант у наказі','profile.head',state.profile.head,'text','maxlength="100"')}${field('Підписант у кошторисі','profile.budgetHead',state.profile.budgetHead,'text','maxlength="100"')}<div class="section-divider"></div><h2>Дані та резервні копії</h2><p class="muted">Звіти зберігаються лише в цьому браузері. Автоматичної синхронізації між пристроями немає. Експортуйте копію перед очищенням даних браузера.</p><div class="button-row">${btn('↓ Завантажити копію','backup','button secondary')}${btn('↑ Відновити з копії','restore','button secondary')}</div><input type="file" id="restore-file" accept="application/json,.json" hidden></div></section><aside class="card"><div class="card-body"><span class="phone-icon">▯</span><h2>Звіт на вашому телефоні</h2><p class="muted">Встановіть застосунок на головний екран, щоб швидко відкривати документи.</p>${btn('Встановити застосунок','install','button wide')}<p class="field-help">iPhone: Safari → Поділитися → На початковий екран.<br><br>Android: меню браузера → Встановити застосунок або Додати на головний екран.</p><div class="section-divider"></div><h3>Підключення та доступ</h3><p class="muted">Застосунок можна встановити на телефон. Захищений робочий простір працює за наявності з’єднання із сервером. Для входу та перевірки доступу потрібне з’єднання із сервером.</p></div></aside></div>`}

const emptyContact=kind=>Object.fromEntries(directoryFields[kind].map(key=>[key,'']));
const contactDrafts={clinics:emptyContact('clinics'),representatives:emptyContact('representatives')};
function contactPicker(kind,target='event'){
 const clinic=kind==='clinics', current=state[target], rows=state[kind];
 const selected=rows.find(r=>r.id===current[clinic?'clinicId':'representativeId']&&(clinic?r.name===current.venue&&r.city===current.city:target==='travel'?r.name===current.driver:r.person===current.person));
 return `<label class="field contact-picker"><span>${clinic?'Збережена клініка':target==='travel'?'Водій із представників':'Збережений представник'}</span><select data-contact-picker="${kind}" data-target="${target}"><option value="">${rows.length?'Виберіть зі збережених або введіть вручну':'Ще немає записів — введіть дані нижче'}</option>${rows.map(r=>`<option value="${esc(r.id)}" ${selected?.id===r.id?'selected':''}>${esc(r.name)}${clinic&&r.city?' · '+esc(r.city):''}</option>`).join('')}</select></label>`;
}
function contactsView(){
 const labels={name:'Назва клініки',city:'Місто',address:'Адреса',contact:'Контактна особа',phone:'Телефон',person:'ПІБ у давальному відмінку (для наказу)'};
 return head('ДОВІДНИКИ','Клініки та представники','Збережіть дані один раз і вибирайте їх у документах.',btn('До документів →','contacts-event','button secondary'))+`<p class="muted">Записи зберігаються на цьому пристрої та входять до резервної копії. Зміни довідника не змінюють раніше заповнені звіти.</p><div class="contacts-layout">${['clinics','representatives'].map(kind=>{const clinic=kind==='clinics',draft=contactDrafts[kind];return `<section class="card"><div class="card-body"><h2>${clinic?'Клініки':'Представники'} <span class="pill">${state[kind].length}</span></h2><p class="muted">${clinic?'Назва й місто підставляються в документи події.':'Відповідальна особа для наказу та ПІБ водія для подорожнього листа. Підписант документів задається в налаштуваннях.'}</p><h3>${draft.id?'Редагування запису':'Новий запис'}</h3>${directoryFields[kind].map(key=>`<label class="field"><span>${key==='name'&&!clinic?'ПІБ представника':labels[key]}${key==='name'||key==='person'?' *':''}</span><input data-directory="${kind}" data-contact-field="${key}" value="${esc(draft[key])}" maxlength="300" type="${key==='phone'?'tel':'text'}"></label>`).join('')}<div class="button-row">${btn(draft.id?'Зберегти зміни':'Додати запис','save-'+kind)}${draft.id?btn('Скасувати','cancel-'+kind,'button secondary'):''}</div><div class="section-divider"></div><div class="contact-list">${state[kind].length?state[kind].map(r=>`<div class="contact-entry"><div><h3>${esc(r.name)}</h3><p>${[clinic?r.city:r.person,clinic?r.address:'',clinic?r.contact:'',r.phone].filter(Boolean).map(esc).join(' · ')}</p></div><div class="button-row"><button class="button secondary" data-edit-contact="${esc(r.id)}" data-contact-kind="${kind}">Редагувати</button><button class="text-button" data-remove-contact="${esc(r.id)}" data-contact-kind="${kind}">Видалити</button></div></div>`).join(''):'<p class="muted">Збережених записів поки немає.</p>'}</div></div></section>`}).join('')}</div>`;
}
function saveContact(kind){
 const draft=contactDrafts[kind],row={id:draft.id||crypto.randomUUID(),...Object.fromEntries(directoryFields[kind].map(k=>[k,draft[k].trim()]))};
 if(!validDirectory([row],kind))return toast(kind==='clinics'?'Введіть назву клініки.':'Введіть ПІБ представника та ПІБ у давальному відмінку.');
 const index=state[kind].findIndex(r=>r.id===row.id);
 if(index<0&&state[kind].length>=500)return toast('У довіднику може бути до 500 записів.');
 if(index<0)state[kind].push(row);else state[kind][index]=row;
 contactDrafts[kind]=emptyContact(kind);save();render();toast(storageOK?'Запис збережено.':'Не вдалося зберегти на пристрої. Завантажте резервну копію.');
}
function rememberContact(kind){
 const clinic=kind==='clinics',e=state.event,name=(clinic?e.venue:e.person).trim();
 if(!name)return toast(clinic?'Спочатку введіть назву клініки.':'Спочатку введіть відповідальну особу.');
 if(!clinic){
  const existing=state.representatives.find(r=>r.person.toLocaleLowerCase('uk')===name.toLocaleLowerCase('uk'));
  if(existing){applyContact(state,kind,existing.id);save();render();return toast('Представника вже збережено.');}
  contactDrafts.representatives={...emptyContact(kind),person:name};view='contacts';render();
  document.querySelector('[data-directory="representatives"]')?.focus();
  return toast('Додайте ПІБ у називному відмінку та збережіть запис.');
 }
 const row=state[kind].find(r=>r.name.toLocaleLowerCase('uk')===name.toLocaleLowerCase('uk')&&(!clinic||r.city.trim().toLocaleLowerCase('uk')===e.city.trim().toLocaleLowerCase('uk')));
 if(row){applyContact(state,kind,row.id);save();render();return toast('Такий запис уже збережено. Змінити його можна в довіднику.');}
 if(state[kind].length>=500)return toast('У довіднику може бути до 500 записів.');
 const record={...emptyContact(kind),id:crypto.randomUUID(),name,...(clinic?{city:e.city.trim()}:{person:name})};
 state[kind].push(record);applyContact(state,kind,record.id);save();render();toast(storageOK?'Дані збережено в довіднику.':'Не вдалося зберегти на пристрої. Завантажте резервну копію.');
}


let accountRows=[];
function accountSettings(){return `<h2>Ваш обліковий запис</h2><p class="muted">${esc(session.user.name)} · ${esc(session.user.username)} · ${session.user.role==='admin'?'Адміністратор':'Представник'}<br>Дані цього облікового запису зберігаються в цьому браузері. Для іншого пристрою перенесіть резервну копію.</p>${session.user.role==='admin'?btn('Керувати користувачами','accounts','button secondary'):''}<details class="travel-details"><summary>Змінити пароль</summary><label class="field"><span>Поточний пароль</span><input id="current-password" type="password" autocomplete="current-password" maxlength="256"></label><label class="field"><span>Новий пароль · від 12 символів</span><input id="new-password" type="password" autocomplete="new-password" minlength="12" maxlength="256"></label><label class="field"><span>Повторіть новий пароль</span><input id="repeat-password" type="password" autocomplete="new-password" maxlength="256"></label>${btn('Змінити пароль','change-password')}</details><div class="section-divider"></div>`;}
function accountsView(){if(session.user.role!=='admin')return '';return head('АДМІНІСТРУВАННЯ','Облікові записи','Створюйте доступ для представників. Паролі зберігаються як захищені хеші.',btn('Оновити список','accounts','button secondary'))+`<div class="contacts-layout"><section class="card"><div class="card-body"><h2>Додати представника</h2><label class="field"><span>ПІБ</span><input id="account-name" maxlength="180" autocomplete="name"></label><label class="field"><span>Логін · латинські літери, цифри, . _ @ -</span><input id="account-username" maxlength="80" autocomplete="off" autocapitalize="none" spellcheck="false"></label><label class="field"><span>Початковий пароль · від 12 символів</span><input id="account-password" type="password" minlength="12" maxlength="256" autocomplete="new-password"></label><p class="field-help">Передайте пароль представнику особисто. Він зможе змінити його в налаштуваннях.</p>${btn('Створити обліковий запис','create-account')}</div></section><section class="card"><div class="card-body"><h2>Користувачі</h2>${accountRows.map(row=>`<div class="contact-entry"><h3>${esc(row.name)}</h3><p>${esc(row.username)} · ${row.role==='admin'?'Адміністратор':'Представник'} · ${row.active?'Доступ активний':'Доступ призупинено'}</p>${row.id===session.user.id?'<span class="pill">Це ви</span>':`<div class="button-row"><button class="button secondary" data-action="toggle-account" data-id="${esc(row.id)}">${row.active?'Призупинити доступ':'Відновити доступ'}</button></div><details class="travel-details"><summary>Скинути пароль</summary><label class="field"><span>Новий пароль · від 12 символів</span><input type="password" id="reset-${esc(row.id)}" autocomplete="new-password" minlength="12" maxlength="256"></label><button class="button secondary" data-action="reset-account-password" data-id="${esc(row.id)}">Зберегти новий пароль</button></details>`}</div>`).join('')}</div></section></div>`;}
async function showAccounts(){try{const data=await api('/api/users');accountRows=data.users;view='accounts';render();}catch(e){toast(e.message);}}
async function createAccount(){const button=document.querySelector('[data-action="create-account"]');button.disabled=true;try{await api('/api/users',{name:$('#account-name').value.trim(),username:$('#account-username').value.trim(),password:$('#account-password').value});await showAccounts();toast('Обліковий запис представника створено.');}catch(e){toast(e.message);button.disabled=false;}}
async function editAccount(action,id){try{const body=action==='toggle-account'?{active:!accountRows.find(row=>row.id===id).active}:{password:document.getElementById('reset-'+id).value};await api('/api/users/'+id,body,'PATCH');await showAccounts();toast(action==='toggle-account'?'Доступ оновлено.':'Пароль змінено. Попередні сесії завершено.');}catch(e){toast(e.message);}}
async function changePassword(){const password=$('#new-password').value;if(password!==$('#repeat-password').value)return toast('Нові паролі не збігаються.');try{await api('/api/password',{currentPassword:$('#current-password').value,password});await logout();}catch(e){toast(e.message);}}

function render(){document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#breadcrumb').textContent={event:'Документи події',travel:'Подорожній лист',archive:'Збережені звіти',settings:'Налаштування',contacts:'Клініки та представники',accounts:'Облікові записи'}[view];$('#content').innerHTML=({event:eventView,travel:travelView,archive:archiveView,settings:settingsView,contacts:contactsView,accounts:accountsView}[view])();$('#archive-count').textContent=state.archive.length;updateDerived()}
function updateDerived(){if(view==='event'){if($('#mini-doc'))$('#mini-doc').innerHTML=documentHtml(docType);if($('#budget-total'))$('#budget-total').innerHTML=money(costTotal(state.event.items))+' <small>₴</small>';state.event.items.forEach((r,i)=>{const el=document.querySelector(`[data-line-total="${i}"]`);if(el)el.textContent=money(r.qty*r.price)+' ₴'});$('#preview-status').textContent=eventErrors(false).length?'Заповніть обов’язкові поля':'Дані події заповнено';const dateInput=$('#order-date');if(dateInput)dateInput.value=date(eventDates(state.event).orderDate)}if(view==='travel'){const r=travelCalc(state.travel);$('#travel-balance').innerHTML=`<div class="balance-main">${r.total===undefined?'—':num(r.total)}<small> км</small></div><p class="muted">Загальний розрахунковий пробіг</p><dl><div><dt>Витрачено пального</dt><dd>${num(state.travel.liters)} л</dd></div><div><dt>Розраховано видано</dt><dd>${r.refill===undefined?'—':num(r.refill)+' л'}</dd></div><div><dt>За нормою</dt><dd>${r.normFuel===undefined?'—':num(r.normFuel)+' л'}</dd></div><div><dt>Фактичні л / 100 км</dt><dd>${r.actualRate===undefined?'—':num(r.actualRate)}</dd></div><div><dt>Факт − норма</dt><dd>${r.fuelDifference===undefined?'—':num(r.fuelDifference)+' л'}</dd></div><div><dt>Залишок на кінець</dt><dd>${r.endFuel===undefined?'—':num(r.endFuel)+' л'}</dd></div><div><dt>Одометр на кінець</dt><dd>${r.endOdo===undefined?'—':num(r.endOdo)+' км'}</dd></div></dl><div class="balance-status ${r.error?'invalid':''}">${r.error?'! '+esc(r.error):'✓ Баланс пального та пробігу сходиться'}</div>`;const refill=$('#auto-refill');if(refill)refill.value=r.refill===undefined?'—':num(r.refill);const last=$('[data-last-km]');if(last)last.value=r.rows?.at(-1)?.km??0}}
function eventErrors(budget){const e=state.event;let errors=[];if(!e.venue.trim())errors.push('назву закладу');if(!validDate(e.date))errors.push('дату круглого столу');if(!eventDates(e).orderDate)errors.push('дату чеку');if(!e.person.trim())errors.push('відповідальну особу');if(!e.products.length)errors.push('хоча б один препарат');if(budget&&(!e.items.length||e.items.some(r=>!r.name.trim()||!(Number(r.qty)>0)||Number(r.price)<0||!Number.isFinite(Number(r.price)))))errors.push('коректні позиції кошторису');return errors}
function travelErrors(){const t=state.travel,r=travelCalc(t);if(r.error)return r.error;if([t.odometer,t.startFuel,t.endTarget].some(n=>!Number.isFinite(Number(n))||Number(n)<0))return 'Залишок, заправка й одометр мають бути невід’ємними.';if(!t.driver.trim()||!t.car.trim()||!t.plate.trim())return 'Заповніть водія, автомобіль і державний номер.';if(!t.from||!t.to||t.to<t.from)return 'Перевірте початок і кінець періоду.';if(t.rows.some(r=>!r.route.trim()||!r.date||r.date<t.from||r.date>t.to))return 'Заповніть маршрути й дати всіх поїздок у межах періоду.';return ''}
function documentHtml(type){const e=state.event,p=state.profile,d=eventDates(e).orderDate,val=s=>esc(s||'________________');if(type==='order')return `<article class="paper order"><h1>Н А К А З №${val(e.number)}</h1><div class="order-date"><span>м. ${val(e.city)}</span><span>${longDate(d)}</span></div><div class="order-subject">«Про організацію круглого столу<br>у ${val(e.venue)}»</div><p class="command">Наказую:</p><p>${val(e.person)} провести круглий стіл ${date(e.date)} року у ${val(e.venue)} по препаратах: ${val(e.products.join(', '))}</p><p class="order-point">1. &nbsp; Скласти кошторис.</p><p>Підстава: Розпорядження керівника.</p><div class="order-sign"><span>${val(p.position)}<br>${val(p.company)}</span><span>${val(p.head)}</span></div></article>`;if(type==='budget'){const total=money(costTotal(e.items));return `<article class="paper budget"><h1>К О Ш Т О Р И С</h1><p class="budget-subject">Про організацію круглого столу у ${val(e.venue)}</p><div class="amount-line">${total}</div><div class="amount-hint">( сума витрат подано в гривнях)</div><table><thead><tr><th>№</th><th>Опис затрат</th><th>Сума</th></tr></thead><tbody>${e.items.map((r,i)=>`<tr><td>${i+1}</td><td>${val(r.name)}</td><td class="amount">${money(r.qty*r.price)}</td></tr>`).join('')}<tr><td>&nbsp;</td><td></td><td></td></tr><tr><td>&nbsp;</td><td></td><td></td></tr><tr><td></td><td>Всього</td><td class="amount">${total}</td></tr></tbody></table><p class="budget-date">дата: ${date(d)}</p><p class="budget-sign">${val(p.position)}:__________________ ${val(p.budgetHead)}</p></article>`}const t=state.travel,r=travelCalc(t);return travelTemplate(t,r)}
function preview(type){docType=type;$('#full-preview').innerHTML=documentHtml(type);$('#preview-dialog').showModal()}
function printDoc(type,both=false){if(type==='travel'){const err=travelErrors();if(err)return toast(err)}else{const errors=eventErrors(type==='budget'||both);if(errors.length)return toast('Заповніть: '+errors.join(', ')+'.')}$('#page-style').textContent=`@page { size: ${type==='travel'?'A5':'A4'} portrait; margin: 0; }`;$('#print-root').innerHTML=both?documentHtml('order')+documentHtml('budget'):documentHtml(type);document.body.classList.add('printing');window.print()}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
function storeReport(type){const errors=type==='event'?eventErrors(true).join(', '):travelErrors();if(errors)return toast(type==='event'?'Заповніть: '+errors:errors);const copy=structuredClone(type==='event'?state.event:state.travel);state.archive.push({id:crypto.randomUUID(),type,title:type==='event'?copy.venue:copy.driver,date:type==='event'?copy.date:copy.from,data:copy,profile:structuredClone(state.profile)});save();toast(storageOK?'Звіт збережено в архіві.':'Не вдалося зберегти. Завантажте резервну копію.');render()}
function backup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`zvit-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validBackup(s){const str=x=>typeof x==='string'&&x.length<2000,arr=x=>Array.isArray(x)&&x.length<500,num=x=>Number.isFinite(Number(x))&&Number(x)>=0;const event=e=>e&&['venue','date','number','city','person'].every(k=>str(e[k]))&&(e.receiptDate===undefined||(str(e.receiptDate)&&(e.receiptDate===''||validDate(e.receiptDate))))&&arr(e.products)&&e.products.every(str)&&arr(e.items)&&e.items.every(r=>str(r.name)&&num(r.qty)&&num(r.price));const travel=t=>t&&['driver','car','plate','from','to'].every(k=>str(t[k]))&&['liters','rate','startFuel','refill','odometer'].every(k=>num(t[k]))&&(t.endTarget===undefined||num(t.endTarget))&&(t.adjustmentKm===undefined||Number.isFinite(Number(t.adjustmentKm)))&&arr(t.rows)&&t.rows.length>0&&t.rows.every(r=>str(r.date)&&str(r.route)&&num(r.km));const profile=p=>p&&['company','head','budgetHead','position'].every(k=>str(p[k]));return s?.version===1&&validDirectory(s.clinics,'clinics')&&validDirectory(s.representatives,'representatives')&&event(s.event)&&travel(s.travel)&&profile(s.profile)&&arr(s.products)&&s.products.every(str)&&arr(s.archive)&&s.archive.every(r=>str(r.id)&&/^[a-zA-Z0-9-]+$/.test(r.id)&&str(r.title)&&str(r.date)&&profile(r.profile)&&(r.type==='event'?event(r.data):r.type==='travel'&&travel(r.data)))}
async function install(){if(deferredInstall){await deferredInstall.prompt();deferredInstall=null}else{toast('iPhone: Safari → Поділитися → На початковий екран. Android: меню → Встановити застосунок.')}}
document.addEventListener('click',async ev=>{const el=ev.target.closest('button');if(!el)return;const ds=el.dataset;if(ds.editContact){const kind=ds.contactKind;contactDrafts[kind]={...state[kind].find(r=>r.id===ds.editContact)};render();document.querySelector(`[data-directory="${kind}"]`)?.focus();return}if(ds.removeContact){const kind=ds.contactKind;if(confirm('Видалити запис із довідника? Дані у звітах залишаться.')){state[kind]=state[kind].filter(r=>r.id!==ds.removeContact);if(contactDrafts[kind].id===ds.removeContact)contactDrafts[kind]=emptyContact(kind);save();render()}return}if(ds.view){view=ds.view;docType=view==='travel'?'travel':'order';render();return}if(ds.tab){eventTab=ds.tab;render();return}if(ds.doc){docType=ds.doc;render();return}if(ds.product){const a=state.event.products;a.includes(ds.product)?a.splice(a.indexOf(ds.product),1):a.push(ds.product);save();render();return}if(ds.removeItem!==undefined){state.event.items.splice(+ds.removeItem,1);save();render();return}if(ds.removeTrip!==undefined&&state.travel.rows.length>1){state.travel.rows.splice(+ds.removeTrip,1);save();render();return}if(ds.stepTrip!==undefined){const r=state.travel.rows[+ds.stepTrip];r.km=Math.max(0,round(Number(r.km)+Number(ds.step)));save();render();return}if(ds.deleteArchive){if(confirm('Видалити збережений звіт? Перед видаленням можна завантажити резервну копію.')){state.archive=state.archive.filter(r=>r.id!==ds.deleteArchive);save();render()}return}const a=ds.action;if(!a)return;if(a==='logout'){try{await logout()}catch(e){toast(e.message)}return}if(a==='accounts'){await showAccounts();return}if(a==='create-account'){await createAccount();return}if(a==='change-password'){await changePassword();return}if(a==='toggle-account'||a==='reset-account-password'){await editAccount(a,ds.id);return}
if(a.startsWith('open-')){const r=state.archive.find(r=>r.id===a.slice(5));if(r&&confirm('Відкрити звіт замість поточної чернетки? Незбережені в архіві зміни чернетки буде замінено.')){state[r.type==='event'?'event':'travel']=structuredClone(r.data);state.profile=structuredClone(r.profile);state.travel.endTarget??=state.travel.startFuel;state.travel.adjustmentKm??=0;view=r.type;docType=r.type==='event'?'order':'travel';save();render()}return}
switch(a){case 'contacts-event':view='event';eventTab='details';docType='order';render();break;case 'manage-contacts':view='contacts';render();break;case 'remember-clinic':rememberContact('clinics');break;case 'remember-representative':rememberContact('representatives');break;case 'save-clinics':case 'save-representatives':saveContact(a.slice(5));break;case 'cancel-clinics':case 'cancel-representatives':contactDrafts[a.slice(7)]=emptyContact(a.slice(7));render();break;case 'preset-seat':case 'preset-vw':{if(!confirm('Завантажити норму, початковий залишок та одометр з Excel? Поточні значення цих полів буде замінено.'))break;const seat=a==='preset-seat';Object.assign(state.travel,{rate:seat?10:9,startFuel:seat?20:25,endTarget:seat?20:25,odometer:seat?12675.7:80238,car:seat?'SEAT':'VW',adjustmentKm:0,basis:seat?'seat · вересень 2026 · D21/F21/G21':'vw · жовтень 2024 · D53/F53/G53'});save();render();break}case 'next-period':{const err=travelErrors();if(err){toast(err);break}if(!confirm('Зберегти поточний звіт і почати наступний місяць із його кінцевим залишком та одометром?'))break;const result=travelCalc(state.travel);storeReport('travel');if(!storageOK)break;const next=new Date(state.travel.to+'T12:00:00Z');next.setUTCDate(1);next.setUTCMonth(next.getUTCMonth()+1);const from=next.toISOString().slice(0,10);next.setUTCMonth(next.getUTCMonth()+1);next.setUTCDate(0);Object.assign(state.travel,{liters:0,startFuel:result.endFuel,endTarget:result.endFuel,odometer:result.endOdo,adjustmentKm:0,from,to:next.toISOString().slice(0,10),basis:'попередній збережений звіт',rows:[{date:from,route:'',km:0}]});save();render();break}case 'new-event':if(confirm('Створити нову подію? Поточна чернетка буде замінена. Спочатку збережіть потрібний звіт.')){state.event=defaults().event;eventTab='details';save();render()}break;case 'next-tab':eventTab=eventTab==='details'?'budget':'details';render();break;case 'add-product':{const p=$('#new-product').value.trim();if(!p)return toast('Введіть назву препарату.');if(!state.products.includes(p))state.products.push(p);if(!state.event.products.includes(p))state.event.products.push(p);save();render();break}case 'add-item':state.event.items.push({name:'',qty:1,price:0});save();render();break;case 'add-trip':{if(state.travel.rows.length>=5){toast('У бланку є 5 рядків завдань. Додаткові деталі можна внести в особливі відмітки.');break}const r=travelCalc(state.travel);if(r.rows)state.travel.rows=r.rows.map(({fuel,...row})=>row);state.travel.rows.push({date:state.travel.to,route:'',km:0});save();render();break}case 'split-trips':{const r=travelCalc(state.travel);if(r.total===undefined)return toast(r.error);state.travel.rows.forEach(row=>row.km=Math.floor(r.total/state.travel.rows.length*100)/100);save();render();break}case 'save-event':storeReport('event');break;case 'save-travel':storeReport('travel');break;case 'preview':preview(docType);break;case 'travel-preview':preview('travel');break;case 'print':printDoc(docType);break;case 'print-both':printDoc('order',true);break;case 'print-travel':printDoc('travel');break;case 'backup':backup();break;case 'restore':$('#restore-file').click();break;case 'install':install();break}});
document.addEventListener('input',ev=>{const el=ev.target,ds=el.dataset;if(ds.directory){contactDrafts[ds.directory][ds.contactField]=el.value;return}if(el.id==='archive-search'){$('#archive-list').innerHTML=archiveList(el.value);return}if(ds.key){const [obj,key]=ds.key.split('.');state[obj][key]=el.type==='number'?Number(el.value):el.value;save();updateDerived()}if(ds.item!==undefined){state.event.items[+ds.item][ds.prop]=ds.prop==='name'?el.value:Number(el.value);save();updateDerived()}if(ds.trip!==undefined&&!el.readOnly){state.travel.rows[+ds.trip][ds.prop]=ds.prop==='km'?Number(el.value):el.value;save();updateDerived()}});
document.addEventListener('change',async ev=>{const picker=ev.target.dataset.contactPicker;if(picker){const target=ev.target.dataset.target||'event';if(ev.target.value)applyContact(state,picker,ev.target.value,target);else delete state[target][picker==='clinics'?'clinicId':'representativeId'];save();render();return}if(ev.target.id!=='restore-file')return;try{const f=ev.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Файл завеликий.');const incoming=JSON.parse(await f.text());if(!validBackup(incoming))throw Error('Невірний формат резервної копії.');if(confirm('Замінити всі поточні дані даними з резервної копії?')){state=migrateDirectories(incoming);state.travel.endTarget??=state.travel.startFuel;state.travel.adjustmentKm??=0;save();render();toast('Дані відновлено.')}}catch(e){toast('Не вдалося відновити: '+e.message)}});
$('#close-preview').onclick=()=>$('#preview-dialog').close();$('#dialog-print').onclick=()=>printDoc(docType);$('#install').onclick=install;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Офлайн-режим недоступний у цьому браузері.'));
$('#account-name-display').textContent=session.user.name;
if(!storageOK)$('#save-state').textContent='Локальне збереження недоступне';render();
